import React, { createContext, useContext, useEffect, useState } from 'react';
import { io } from 'socket.io-client';
import { useAuth } from './AuthContext';
import toast from 'react-hot-toast';

const SocketContext = createContext();

export const SocketProvider = ({ children }) => {
  const [socket, setSocket] = useState(null);
  const [isConnected, setIsConnected] = useState(false);
  const { user, isAuthenticated } = useAuth();

  useEffect(() => {
    if (!isAuthenticated || !user) {
      return; // Don't connect if not authenticated
    }

    // Initialize socket connection
    const newSocket = io(process.env.REACT_APP_SERVER_URL || 'http://localhost:5000', {
      transports: ['websocket', 'polling'], // Fallback to polling if websocket fails
      upgrade: true,
      reconnection: true,
      reconnectionDelay: 1000,
      reconnectionAttempts: 5
    });

      newSocket.on('connect', () => {
        console.log('✅ Socket connected:', newSocket.id);
        setIsConnected(true);

        // Join user-specific room
        newSocket.emit('join-user-room', user._id);
      });

      newSocket.on('disconnect', () => {
        console.log('❌ Socket disconnected');
        setIsConnected(false);
      });

      // Listen for transaction updates
      newSocket.on('transaction-update', (data) => {
        console.log('📱 Transaction update received:', data);

        switch (data.type) {
          case 'MONEY_RECEIVED':
            toast.success(
              `💰 ₹${data.transaction.amount.toLocaleString('en-IN')} received!`,
              {
                duration: 5000,
                icon: '💰'
              }
            );
            break;

          case 'MONEY_ADDED':
            toast.success(
              `✅ ₹${data.transaction.amount.toLocaleString('en-IN')} added to wallet!`,
              {
                duration: 4000,
                icon: '✅'
              }
            );
            break;

          case 'TRANSFER_SENT':
            toast.success(
              `📤 ₹${data.transaction.amount.toLocaleString('en-IN')} sent successfully!`,
              {
                duration: 4000,
                icon: '📤'
              }
            );
            break;

          default:
            toast.success('Transaction completed!');
        }

        // Trigger custom event for components to listen
        window.dispatchEvent(new CustomEvent('walletUpdate', {
          detail: {
            newBalance: data.newBalance,
            transaction: data.transaction
          }
        }));
      });

      // Listen for payment notifications
      newSocket.on('payment-notification', (data) => {
        console.log('💳 Payment notification:', data);

        if (data.type === 'payment-success') {
          toast.success('Payment successful!', {
            duration: 4000,
            icon: '💳'
          });
        } else if (data.type === 'payment-failed') {
          toast.error('Payment failed. Please try again.', {
            duration: 5000,
            icon: '❌'
          });
        }
      });

      // Listen for security alerts
      newSocket.on('security-alert', (data) => {
        console.log('🔒 Security alert:', data);

        toast.error(data.message, {
          duration: 8000,
          icon: '🔒'
        });
      });

      setSocket(newSocket);

      // Cleanup on unmount or when dependencies change
      return () => {
        console.log('🔌 Cleaning up socket connection');
        if (newSocket && newSocket.connected) {
          newSocket.disconnect();
        }
        setSocket(null);
        setIsConnected(false);
      };
  }, [isAuthenticated, user?._id]); // Only depend on user._id, not entire user object

  // Emit events
  const emitEvent = (eventName, data) => {
    if (socket && isConnected) {
      socket.emit(eventName, data);
    } else {
      console.warn('Socket not connected. Cannot emit event:', eventName);
    }
  };

  // Listen to custom events
  const addEventListener = (eventName, callback) => {
    if (socket) {
      socket.on(eventName, callback);

      // Return cleanup function
      return () => {
        socket.off(eventName, callback);
      };
    }
  };

  const value = {
    socket,
    isConnected,
    emitEvent,
    addEventListener
  };

  return (
    <SocketContext.Provider value={value}>
      {children}
    </SocketContext.Provider>
  );
};

export const useSocket = () => {
  const context = useContext(SocketContext);
  if (!context) {
    throw new Error('useSocket must be used within a SocketProvider');
  }
  return context;
};
